const escapeHTML=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let account={loading:true,user:null,error:''},aboutContent={name:'',history:'',concept:'One frame, ready for more. DOOK combines Danish eyewear design with magnetic click-ons that attach to your matching frame. Change your lenses as your day changes, while keeping the glasses you know.',why:'Choose a frame that feels like you, then add matching DOOKs for more possibilities. The magnetic system makes changing between your everyday glasses and sun lenses simple, with advice and fitting from your optician.',instagram:'https://www.instagram.com/dook_denmark/',linkedin:'https://www.linkedin.com/company/dook-denmark/',facebook:'https://www.facebook.com/profile.php?id=61572809430865'},priceData=null,adminData=null;
const isAdmin=()=>account.user?.role==='admin';
const canPrice=()=>['admin','approved'].includes(account.user?.role);
async function api(path,method='GET',data){const r=await fetch(path,{method,credentials:'same-origin',cache:'no-store',headers:method==='GET'?{}:{'Content-Type':'application/json'},body:data?JSON.stringify(data):undefined});let result;try{result=await r.json()}catch{throw new Error('This service is temporarily unavailable. Please try again.')}if(!r.ok)throw new Error(result.error||'Please try again.');return result}
const paragraphs=value=>escapeHTML(value).split(/\n\s*\n/).map(p=>`<p>${p.replace(/\n/g,'<br>')}</p>`).join('');
const signIn=()=>`<a class="pill" href="/signin-with-chatgpt?return_to=${encodeURIComponent('/'+(location.hash.startsWith('#activate/')?location.hash:'#login'))}" target="_top">Sign in with ChatGPT <span>↗</span></a>`;
const signOut=()=>`<a class="text-link" href="/signout-with-chatgpt?return_to=%2F%23login" target="_top">Sign out</a>`;
function aboutPage(){return renderTopbar('ABOUT DOOK')+`<section class="page-head"><span class="eyebrow">A DIFFERENT WAY OF LOOKING AT THINGS</span><h1>One frame.<br>So many possibilities.</h1>${isAdmin()?'<a class="pill outline" href="#admin">Edit our story ↗</a>':''}</section><section class="section about-layout"><div class="about-image"><img src="/assets/hero.webp" alt="The detail of a DOOK Havana frame"></div><div><span class="eyebrow">THE CONCEPT</span><h2>A simple click.<br>A different view.</h2>${paragraphs(aboutContent.concept)}<a class="text-link" href="#collection">Discover the collection ↗</a></div></section>${aboutContent.name?`<section class="section story-row"><div><span class="eyebrow">THE NAME</span><h2>Why DOOK?</h2></div><div>${paragraphs(aboutContent.name)}</div></section>`:''}${aboutContent.history?`<section class="section story-row"><div><span class="eyebrow">OUR STORY</span><h2>Where it all began.</h2></div><div>${paragraphs(aboutContent.history)}</div></section>`:''}<section class="manifesto"><div><span class="eyebrow">WHY CHOOSE DOOK?</span><h2>Designed for<br>your everyday.</h2></div><div>${paragraphs(aboutContent.why)}<a href="#collection" class="pill light">Find your frame ↗</a></div></section><section class="section social-section"><span class="eyebrow">KEEP IN TOUCH</span><h2>Please follow us<br>on social media.</h2><div class="social-links">${['instagram','linkedin','facebook'].filter(k=>aboutContent[k]).map(k=>`<a href="${escapeHTML(aboutContent[k])}" target="_blank" rel="noopener noreferrer">${{instagram:'Instagram',linkedin:'LinkedIn',facebook:'Facebook'}[k]} <span>↗</span></a>`).join('')}</div></section>`+footer()}
function loginPage(){let content;
 if(account.loading)content='<p role="status">Loading your account…</p>';
 else if(account.error)content=`<p role="alert">${escapeHTML(account.error)}</p><button class="pill" data-retry-account>Try again</button>`;
 else if(!account.user)content=`<h2>Welcome back.</h2><p>Sign in to view trade prices for frames and DOOKs. Price access is reserved for approved optical partners.</p>${signIn()}<p class="note">Use your ChatGPT account. New partners can request access after signing in.</p>`;
 else if(canPrice())content=`<span class="eyebrow">${isAdmin()?'DOOK ADMINISTRATION':'APPROVED OPTICAL PARTNER'}</span><h2>You’re signed in.</h2><p>${escapeHTML(account.user.email)}</p><div class="button-row"><a href="#partners" class="pill">View partner collection ↗</a>${isAdmin()?'<a class="pill outline" href="#admin">Administration</a>':''}${signOut()}</div>`;
 else if(account.user.role==='pending')content=`<h2>Thank you.</h2><p>Your request is awaiting DOOK’s approval. Prices become available here once your company has been approved.</p><p>${escapeHTML(account.user.email)}</p><div class="button-row"><button class="pill outline" data-retry-account>Check access</button>${signOut()}</div>`;
 else if(account.user.role==='revoked')content=`<h2>Contact DOOK.</h2><p>Your price access is currently inactive. Please contact us to review your account.</p><div class="button-row"><a class="pill" href="#contact">Contact DOOK</a>${signOut()}</div>`;
 else content=`<h2>Become a partner.</h2><p>Signed in as ${escapeHTML(account.user.email)}. Tell us about your company so we can approve your access.</p><form id="access-form"><label>Your name<input name="name" autocomplete="name" maxlength="200" required></label><label>Company / optical store<input name="company" autocomplete="organization" maxlength="200" required></label><button class="pill">Request price access ↗</button><p class="form-status" role="status"></p></form>${signOut()}`;
 return renderTopbar('B2B LOGIN')+`<section class="login-layout"><div><span class="eyebrow">FOR OPTICAL PARTNERS</span><h1>A better view.<br>Together.</h1><p>Your DOOK collection.<br>Your professional prices.</p><img src="/assets/dook-bookmark.png" alt="" class="login-mark"></div><div class="login-card">${content}<p><a class="text-link" href="#partners">Explore the partner shop ↗</a></p></div></section>`+footer()}
function priceSummary(id){return `<span class="trade-card-price" data-price-model="${escapeHTML(id)}"></span>`}
function partners(){
 if(!canPrice())return loginPage();
 let page=partnerCollection();
 const banner=`<div class="partner-account"><span>${escapeHTML(account.user.email)}</span><div class="button-row">${isAdmin()?'<a href="#admin">Administration ↗</a>':''}${signOut()}</div></div>`;
 const prices=priceData?.config.enabled?`<section class="section"><div class="section-title"><div><span class="eyebrow">FRAMES & DOOKS</span><h2>Your trade prices.</h2></div></div><p>${escapeHTML(priceData.config.currency)} · ${escapeHTML(priceData.config.tax)}</p><label class="price-search">Find a frame or DOOK<input id="price-search" type="search" placeholder="Model, item or colour…"></label><div id="price-results">${priceTable(priceData.prices)}</div></section>`:`<section class="section"><h2>Trade prices</h2><p>${isAdmin()?'Your imported price list is a draft. Review the list and activate it in Administration.':'Prices are being updated. Please contact DOOK for a quote.'}</p>${isAdmin()?'<a class="pill" href="#admin">Review price list ↗</a>':''}</section>`;
 return banner+page.replace(footer(),prices+footer());
}
function detailPriceHTML(){return '<div class="trade-price" aria-live="polite"></div>'}
function money(n){return new Intl.NumberFormat('en-GB',{style:'currency',currency:priceData?.config?.currency||'DKK'}).format(n)}
function refreshPrices(){
 document.querySelectorAll('[data-price-model]').forEach(el=>{el.textContent='';if(!canPrice()||!priceData||!priceData.config.enabled)return;const rows=priceData.prices.filter(r=>r.model===el.dataset.priceModel);if(rows.length)el.textContent=`From ${money(Math.min(...rows.map(r=>r.amount)))}`});
 const box=document.querySelector('.trade-price');if(!box)return;
 if(!canPrice()){box.innerHTML='<a href="#login">B2B customer? Sign in to view prices ↗</a>';return}
 if(!priceData){box.textContent='Loading trade prices…';return}
 if(!priceData.config.enabled){box.innerHTML=isAdmin()?'<a href="#admin">Review and activate your price list ↗</a>':'Trade prices are being updated. Contact DOOK for a quote.';return}
 const p=products.find(p=>p.id===detailModel),v=p?.variants[variantIndex];if(!p||!v)return;
 const rows=priceData.prices.filter(r=>r.model===p.id&&r.colour===v.code);
 const values=[...new Set(rows.map(r=>r.amount))];let text=values.length?`${values.length>1?'From ':''}${money(Math.min(...values))}`:'Price on request';
 box.innerHTML=`<span class="eyebrow">YOUR TRADE PRICE</span><strong>${escapeHTML(text)}</strong><small>${escapeHTML(priceData.config.currency)} · ${escapeHTML(priceData.config.tax)}</small>`;
 if(lensIndex>=0){const lens=window.dookLenses[lensIndex],model=p.id==='A001'?'D01':p.id==='AN001'?'DN01':null;const code=['GN01-3','MI01','BR01-GR-2','BR01-3','CL01-AB','GY01-GR-2','GY01-3-PL','YE01-NV','CL01-AB+1,0','BL01-GR-1'][lensIndex];const clips=priceData.prices.filter(r=>r.model===model&&r.colour===code);box.innerHTML+=`<div class="clip-price">DOOK · ${escapeHTML(lens.name)}<b>${clips.length?'From '+money(Math.min(...clips.map(r=>r.amount))):'Price on request'}</b></div><small>Match the exact model and size in the partner price list.</small>`}
}
function adminPage(){if(!isAdmin())return loginPage();return renderTopbar('DOOK ADMINISTRATION')+`<section class="page-head"><span class="eyebrow">YOUR WEBSITE</span><h1>Make it your story.</h1><p>Edit your About DOOK page, approve partners and review prices.</p><div class="button-row"><a class="pill" href="#partners">Open partner shop ↗</a><a class="pill outline" href="#news-edit">Manage News ↗</a></div></section><section class="section admin-section"><h2>About DOOK</h2><form id="about-form">${[['name','Why is it called DOOK?'],['concept','The concept'],['history','Our history and background'],['why','Why choose DOOK?']].map(([key,label])=>`<label>${label}<textarea name="${key}" maxlength="8000" rows="5" placeholder="Write your explanation here…">${escapeHTML(aboutContent[key])}</textarea></label>`).join('')}<p class="note">Empty name and history fields stay hidden on the public page. Your text is saved for all visitors.</p><div class="social-fields">${['instagram','linkedin','facebook'].map(k=>`<label>${{instagram:'Instagram',linkedin:'LinkedIn',facebook:'Facebook'}[k]}<input type="url" name="${k}" value="${escapeHTML(aboutContent[k])}" placeholder="https://"></label>`).join('')}</div><div class="button-row"><button class="pill">Save About DOOK</button><a href="#about" class="text-link">View page ↗</a></div><p class="form-status" role="status"></p></form></section><section class="section admin-section"><h2>Partner access</h2><div id="partner-management">Loading partners…</div></section><section class="section admin-section"><h2>Trade prices</h2><p>Draft imported from the PurchasePrice column in FrameCatalog-V2-20260911(2).xlsx, updated 18 September 2026. Check the prices, currency and VAT before making them visible to approved partners.</p><form id="pricing-form"><div class="form-row"><label>Currency<select name="currency"><option>DKK</option><option>EUR</option></select></label><label>VAT<select name="tax"><option>excl. VAT</option><option>incl. VAT</option></select></label></div><label class="checkbox-label"><input name="enabled" type="checkbox"> I have checked the price list. Show it to approved partners.</label><button class="pill">Save price settings</button><p class="form-status" role="status"></p></form><div id="admin-price-list"></div></section>`+footer()}
function priceTable(rows){return `<div class="price-table-wrap"><table class="price-table"><thead><tr><th>Item</th><th>Description</th><th>Trade price</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${escapeHTML(r.sku)}</td><td>${escapeHTML(r.description)}</td><td>${money(r.amount)}</td></tr>`).join('')}</tbody></table></div>`}
function fillAdmin(){if(!isAdmin())return;const box=document.querySelector('#partner-management');if(box&&adminData){box.innerHTML=adminData.partners.length?adminData.partners.map(p=>`<div class="partner-row"><div><strong>${escapeHTML(p.company)}</strong><p>${escapeHTML(p.name)} · ${escapeHTML(p.email)}</p><span class="note">${escapeHTML(p.status)}</span></div><button class="pill outline" data-partner-id="${escapeHTML(p.user_id)}" data-partner-status="${p.status==='approved'?'revoked':'approved'}">${p.status==='approved'?'Revoke access':'Approve access'}</button></div>`).join(''):'<p>No partner requests yet.</p>';const f=document.querySelector('#pricing-form');f.elements.currency.value=adminData.config.currency;f.elements.tax.value=adminData.config.tax;f.elements.enabled.checked=adminData.config.enabled}
 const list=document.querySelector('#admin-price-list');if(list&&priceData)list.innerHTML=`<label class="price-search">Find a frame or DOOK<input id="price-search" type="search" placeholder="Model, item or colour…"></label><p class="note">${priceData.prices.length} items · ${escapeHTML(priceData.config.tax)} · ${priceData.config.enabled?'Visible to approved partners':'Draft — hidden from partners'}</p><div id="price-results">${priceTable(priceData.prices)}</div>`;
}
async function loadAccount(){try{account={loading:false,...await api('/api/me'),error:''};priceData=null;if(canPrice())priceData=await api('/api/prices');if(isAdmin())adminData=await api('/api/admin')}catch(e){account.loading=false;account.error=e.message}document.querySelector('.partner-link').innerHTML=`${canPrice()?'Partner shop':'B2B login'} <span>↗</span>`;document.querySelector('.partner-link').href=canPrice()?'#partners':'#login';if(canPrice()&&location.hash==='#login')history.replaceState(null,'','#partners');if(['#login','#partners','#admin','#selection','#about'].includes(location.hash)||location.hash.startsWith('#news-edit'))render();else refreshPrices();}
async function initializeB2B(){
 const activation=location.hash.startsWith('#activate/')?location.hash.slice(10):null;
 try{aboutContent=(await api('/api/about')).content}catch{}
 await loadAccount();
 if(activation){try{await api('/api/activate-owner','POST',{token:activation});history.replaceState(null,'','#admin');await loadAccount()}catch(e){app.innerHTML=renderTopbar('ADMINISTRATION')+`<section class="section"><h1>Activate administration</h1><p role="alert">${escapeHTML(e.message)}</p><p>Open your activation link while signed in to the owner’s account.</p>${signIn()}</section>`}return}
 if(location.hash==='#about')render();
}
document.addEventListener('submit',async e=>{
 if(!['about-form','access-form','pricing-form'].includes(e.target.id))return;e.preventDefault();const form=e.target,button=form.querySelector('button'),status=form.querySelector('.form-status'),f=new FormData(form);button.disabled=true;status.textContent='Saving…';
 try{if(form.id==='about-form'){const r=await api('/api/about','PUT',Object.fromEntries(f));aboutContent=r.content;status.textContent='Saved. Your About DOOK page is updated.'}
 else if(form.id==='access-form'){await api('/api/access-request','POST',Object.fromEntries(f));await loadAccount()}
 else{await api('/api/admin/pricing','PUT',{currency:f.get('currency'),tax:f.get('tax'),enabled:f.has('enabled')});priceData=await api('/api/prices');adminData.config=priceData.config;status.textContent='Price settings saved.';document.querySelector('#admin-price-list').innerHTML=priceTable(priceData.prices)}
 }catch(error){status.textContent=error.message}finally{button.disabled=false}
});
document.addEventListener('click',async e=>{if(e.target.closest('[data-retry-account]'))await loadAccount();const b=e.target.closest('[data-partner-id]');if(b){b.disabled=true;try{await api('/api/admin/partner','PUT',{id:b.dataset.partnerId,status:b.dataset.partnerStatus});adminData=await api('/api/admin');fillAdmin()}catch(error){b.after(Object.assign(document.createElement('p'),{textContent:error.message}));b.disabled=false}}});
document.addEventListener('input',e=>{if(e.target.id==='price-search'){const q=e.target.value.toLowerCase();document.querySelector('#price-results').innerHTML=priceTable(priceData.prices.filter(p=>(p.sku+' '+p.description).toLowerCase().includes(q)))}});
